from rules import solve as _solve


def solve(data):
    return _solve(data)

def solve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])
    names = sorted(packages)

    bounds = {name: (low, high) for name, (low, high) in roots.items()}
    best_versions = None
    best_vector = None

    def in_bounds(name, version, limits):
        low, high = limits.get(name, (None, None))
        return (low is None or version >= low) and (high is None or version <= high)

    def is_acyclic(edges):
        state = {}

        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for dependency in edges.get(name, ()):
                if not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in edges)

    def search(assignments, required, limits, edges):
        nonlocal best_versions, best_vector

        pending = sorted(required - assignments.keys())
        if not pending:
            if not is_acyclic(edges):
                return
            vector = tuple(assignments.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(assignments)
            return

        name = pending[0]
        if name not in packages:
            return

        for row in packages[name]:
            version = row['version']
            if version in blocked.get(name, ()):
                continue
            if name in pins and version != pins[name]:
                continue
            if not in_bounds(name, version, limits):
                continue

            updated_assignments = dict(assignments)
            updated_assignments[name] = version
            updated_required = set(required)
            updated_limits = dict(limits)
            active_dependencies = []
            valid = True

            for dependency in row.get('deps', []):
                if isinstance(dependency, dict):
                    feature = dependency.get('feature')
                    if feature and feature not in features:
                        continue
                    dep_name = dependency['name']
                    dep_low = dependency['min']
                    dep_high = dependency['max']
                else:
                    dep_name = dependency
                    dep_low = dep_high = None

                if dep_name not in packages:
                    valid = False
                    break

                old_low, old_high = updated_limits.get(dep_name, (None, None))
                if dep_low is not None:
                    old_low = dep_low if old_low is None else max(old_low, dep_low)
                if dep_high is not None:
                    old_high = dep_high if old_high is None else min(old_high, dep_high)
                if old_low is not None and old_high is not None and old_low > old_high:
                    valid = False
                    break

                updated_limits[dep_name] = (old_low, old_high)
                updated_required.add(dep_name)
                active_dependencies.append(dep_name)
                if dep_name in updated_assignments and not in_bounds(
                    dep_name, updated_assignments[dep_name], updated_limits
                ):
                    valid = False
                    break

            if valid:
                updated_edges = dict(edges)
                updated_edges[name] = active_dependencies
                search(updated_assignments, updated_required, updated_limits, updated_edges)

    search({}, set(roots), bounds, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
